-- food-aggregator / OMS order database (PostgreSQL 16+), schema "order", owned by order-domain
-- First launch: ONE status column + config mapper. UUID v7 generated by order-domain.
-- money: bigint minor units (THB satang). times: timestamptz.

CREATE SCHEMA IF NOT EXISTS "order";
SET search_path TO "order";

-- 0. order_statuses: single status catalog (rank + terminal). Prefer a lookup table over a PG enum
--    so status_mappings can FK to it, reserved future values can be seeded inactive, and rank
--    lives in the DB next to the mapper (no hardcoded rank in Go for launch).
CREATE TABLE order_statuses (
  code         text     PRIMARY KEY,
  rank         smallint NOT NULL,              -- progress order; ignore regressions (lower rank)
  is_terminal  boolean  NOT NULL DEFAULT false,
  is_active    boolean  NOT NULL DEFAULT true, -- false = reserved for later (own channel / postpaid)
  description  text
);

-- 1. status_mappings: vendor raw -> status_code. New vendor = new rows, no code.
CREATE TABLE status_mappings (
  id            bigint   GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  source        text     NOT NULL,             -- GRAB, LINEMAN, BSL, SDM, OWN_FLEET, PAYMENT, ...
  raw_status    text     NOT NULL,             -- vendor value as received
  status_code   text     NOT NULL REFERENCES order_statuses(code),
  is_active     boolean  NOT NULL DEFAULT true,
  note          text,
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX status_mappings_uk ON status_mappings (source, raw_status) WHERE is_active;

-- 2. orders: one row per channel order. Aggregator = prepaid today.
CREATE TABLE orders (
  id                  uuid        PRIMARY KEY,
  ref_id              text        NOT NULL UNIQUE,   -- grab_{mid}_{oid} | lm_{mid}_{oid}; external idempotency key
  channel             text        NOT NULL CHECK (channel IN ('GRAB','LINEMAN','SHOPEEFOOD','ROBINHOOD','FOODPANDA','OWN_APP','OWN_WEB')),
  channel_order_id    text        NOT NULL,
  channel_short_code  text,
  channel_merchant_id text,
  brand_id            text,                          -- primary brand (subs may differ when split)
  store_id            text,                          -- primary store
  fulfillment_type    text        NOT NULL CHECK (fulfillment_type IN ('DELIVERY','PICKUP','DINE_IN')),
  payment_mode        text        NOT NULL DEFAULT 'PREPAID' CHECK (payment_mode IN ('PREPAID','POSTPAID','PAY_ON_DELIVERY')),
  delivery_provider   text        NOT NULL DEFAULT 'NONE' CHECK (delivery_provider IN ('GRAB','LINEMAN','OWN_FLEET','NONE')),
  scheduled_for       timestamptz,
  customer            jsonb,                         -- masked snapshot
  delivery_address    jsonb,                         -- masked snapshot
  items               jsonb,                         -- full order lines snapshot
  currency            char(3)     NOT NULL DEFAULT 'THB',
  subtotal            bigint      NOT NULL DEFAULT 0,
  discount_total      bigint      NOT NULL DEFAULT 0,
  delivery_fee        bigint      NOT NULL DEFAULT 0,
  service_charge      bigint      NOT NULL DEFAULT 0,
  tax_total           bigint      NOT NULL DEFAULT 0,
  grand_total         bigint      NOT NULL DEFAULT 0,
  status              text        NOT NULL DEFAULT 'RECEIVED' REFERENCES order_statuses(code),
  status_reason       text,                          -- cancel reason, ops note, failure code
  status_changed_at   timestamptz NOT NULL DEFAULT now(),
  first_raw_id        text,                          -- Mongo order_raw._id of create
  placed_at           timestamptz NOT NULL,
  completed_at        timestamptz,
  cancelled_at        timestamptz,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  version             integer     NOT NULL DEFAULT 0, -- optimistic lock
  UNIQUE (channel, channel_merchant_id, channel_order_id),
  CHECK (delivery_provider = 'NONE' OR fulfillment_type = 'DELIVERY')
);
CREATE INDEX orders_open_idx   ON orders (status_changed_at)
  WHERE status NOT IN ('COMPLETED','CANCELLED','REJECTED','FAILED');
CREATE INDEX orders_placed_idx ON orders (placed_at);

-- 3. order_subs: one POS ticket per brand/store/POS. Same order_statuses values.
--    orders.status is rolled up from subs + delivery events in the same transaction.
CREATE TABLE order_subs (
  id                  uuid        PRIMARY KEY,
  order_id            uuid        NOT NULL REFERENCES orders(id),
  seq                 smallint    NOT NULL CHECK (seq >= 1),
  ref_id              text        NOT NULL UNIQUE,   -- {orders.ref_id}#{seq}, passed to POS
  brand_id            text        NOT NULL,
  store_id            text        NOT NULL,
  pos_type            text        NOT NULL CHECK (pos_type IN ('BSL','SDM','PROMISE','NEXA_POS')),
  pos_store_ref       text        NOT NULL,
  pos_order_id        text,                          -- set after POS ack; UNIQUE with pos_type
  items               jsonb,                         -- lines for this POS ticket
  currency            char(3)     NOT NULL DEFAULT 'THB',
  subtotal            bigint      NOT NULL DEFAULT 0,
  discount_total      bigint      NOT NULL DEFAULT 0,
  tax_total           bigint      NOT NULL DEFAULT 0,
  grand_total         bigint      NOT NULL DEFAULT 0,
  status              text        NOT NULL DEFAULT 'RECEIVED' REFERENCES order_statuses(code),
  status_reason       text,
  status_changed_at   timestamptz NOT NULL DEFAULT now(),
  attempt_count       smallint    NOT NULL DEFAULT 0, -- submit retries
  next_attempt_at     timestamptz,
  last_error          text,
  submitted_at        timestamptz,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  version             integer     NOT NULL DEFAULT 0,
  UNIQUE (order_id, seq)
);
CREATE UNIQUE INDEX order_subs_pos_order_uk ON order_subs (pos_type, pos_order_id) WHERE pos_order_id IS NOT NULL;
CREATE INDEX order_subs_stuck_idx ON order_subs (status, next_attempt_at)
  WHERE status IN ('RECEIVED','CONFIRMED');

-- 4. order_status_history: append-only audit + dedup (UNIQUE source,event_id). No separate inbox.
CREATE TABLE order_status_history (
  id           bigint      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  order_id     uuid        NOT NULL REFERENCES orders(id),
  sub_id       uuid        REFERENCES order_subs(id),  -- null = order-level (e.g. delivery)
  source       text        NOT NULL,                   -- GRAB, LINEMAN, BSL, SDM, ADMIN, SYSTEM, ...
  raw_status   text,                                   -- vendor value before map
  from_status  text,
  to_status    text        NOT NULL,
  applied      boolean     NOT NULL DEFAULT true,      -- false = recorded but ignored (rank / stale)
  event_id     text        NOT NULL,
  reason       text,
  raw_id       text,                                   -- Mongo order_raw._id
  occurred_at  timestamptz NOT NULL,
  recorded_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (source, event_id)
);
CREATE INDEX order_status_history_order_idx ON order_status_history (order_id, recorded_at);

-- 5. outbox: reliable Kafka publish (same tx as status change)
CREATE TABLE outbox (
  id             uuid        PRIMARY KEY,              -- event_id
  aggregate_type text        NOT NULL CHECK (aggregate_type IN ('ORDER','SUB')),
  aggregate_id   uuid        NOT NULL,
  partition_key  text        NOT NULL,                 -- orders.ref_id
  topic          text        NOT NULL DEFAULT 'order.events.v1',
  event_type     text        NOT NULL,
  payload        jsonb       NOT NULL,
  headers        jsonb,
  created_at     timestamptz NOT NULL DEFAULT now(),
  published_at   timestamptz,
  attempts       integer     NOT NULL DEFAULT 0
);
CREATE INDEX outbox_unpublished_idx ON outbox (created_at) WHERE published_at IS NULL;
